<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Snake</title>
<style>
  :root{
    --bg:#0b0f14;
    --panel:#121822;
    --edge:#1f2a38;
    --text:#e6edf5;
    --muted:#8ea0b6;
    --accent:#3ddc84;
    --accent-2:#2bb56b;
    --food:#ff5d73;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    background:radial-gradient(1200px 700px at 50% -10%, #16202c 0%, var(--bg) 60%);
    color:var(--text);
    font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    display:flex;
    align-items:center;
    justify-content:center;
    padding:24px;
  }
  .wrap{
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:14px;
  }
  h1{
    margin:0;
    font-size:22px;
    letter-spacing:.28em;
    text-transform:uppercase;
    color:var(--muted);
    font-weight:600;
  }
  .hud{
    width:100%;
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:16px;
    font-variant-numeric:tabular-nums;
  }
  .stat{
    background:var(--panel);
    border:1px solid var(--edge);
    border-radius:10px;
    padding:8px 14px;
    font-size:14px;
    color:var(--muted);
  }
  .stat b{color:var(--text);font-size:18px;margin-left:8px}
  .board{
    position:relative;
    background:var(--panel);
    border:1px solid var(--edge);
    border-radius:14px;
    padding:10px;
    box-shadow:0 20px 60px rgba(0,0,0,.55);
    line-height:0;
  }
  canvas{
    display:block;
    border-radius:8px;
    background:#0d131b;
  }
  #overlay{
    position:absolute;
    inset:10px;
    border-radius:8px;
    display:none;
    align-items:center;
    justify-content:center;
    flex-direction:column;
    gap:6px;
    background:rgba(8,12,17,.72);
    backdrop-filter:blur(2px);
    line-height:1.4;
    text-align:center;
  }
  #overlay.show{display:flex}
  #overlay .big{font-size:26px;font-weight:700;letter-spacing:.06em}
  #overlay .sub{font-size:13px;color:var(--muted)}
  .controls{display:flex;gap:10px}
  button{
    font:inherit;
    font-size:14px;
    color:var(--text);
    background:var(--panel);
    border:1px solid var(--edge);
    border-radius:10px;
    padding:9px 18px;
    cursor:pointer;
    transition:background .12s ease,border-color .12s ease,transform .06s ease;
  }
  button:hover{background:#18202c;border-color:#2c3a4c}
  button:active{transform:translateY(1px)}
  #start{border-color:var(--accent-2);color:var(--accent)}
  .hint{font-size:12px;color:var(--muted);letter-spacing:.04em}
</style>
</head>
<body>
<div class="wrap">
  <h1>Snake</h1>

  <div class="hud">
    <div class="stat">Score <b id="score">0</b></div>
    <div class="stat">Best <b id="best">0</b></div>
  </div>

  <div class="board">
    <canvas id="snake" width="440" height="440"></canvas>
    <div id="overlay"><div class="big" id="ovTitle">Ready</div><div class="sub" id="ovSub">Press Start</div></div>
  </div>

  <div class="controls">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>

  <div class="hint">Arrow keys to steer &middot; Space to pause</div>
</div>

<script>
(function(){
  "use strict";

  var W = 20, H = 20, CELL = 22;
  var canvas = document.getElementById('snake');
  var ctx = canvas.getContext('2d');
  canvas.width = W * CELL;
  canvas.height = H * CELL;

  var scoreEl = document.getElementById('score');
  var bestEl = document.getElementById('best');
  var overlay = document.getElementById('overlay');
  var ovTitle = document.getElementById('ovTitle');
  var ovSub = document.getElementById('ovSub');

  var snake, dir, nextDir, food, alive, score, best = 0;
  var timer = null, running = false, speed = 110;

  var DIRS = {
    up:    [0, -1],
    down:  [0, 1],
    left:  [-1, 0],
    right: [1, 0]
  };
  var OPP = { up:'down', down:'up', left:'right', right:'left' };

  function showOverlay(title, sub){
    ovTitle.textContent = title;
    ovSub.textContent = sub;
    overlay.classList.add('show');
  }
  function hideOverlay(){ overlay.classList.remove('show'); }

  function occupied(x, y){
    for (var i = 0; i < snake.length; i++){
      if (snake[i][0] === x && snake[i][1] === y) return true;
    }
    return false;
  }

  function placeFood(){
    var free = [];
    for (var y = 0; y < H; y++){
      for (var x = 0; x < W; x++){
        if (!occupied(x, y)) free.push([x, y]);
      }
    }
    if (!free.length){ food = null; return; }
    food = free[Math.floor(Math.random() * free.length)].slice();
  }

  function reset(){
    var cy = Math.floor(H / 2), cx = Math.floor(W / 2);
    snake = [[cx, cy], [cx - 1, cy], [cx - 2, cy]];
    dir = 'right';
    nextDir = 'right';
    alive = true;
    score = 0;
    speed = 110;
    placeFood();
    updateHud();
    hideOverlay();
    draw();
    if (running) restartTimer();
    return true;
  }

  function updateHud(){
    scoreEl.textContent = String(score);
    if (score > best){ best = score; }
    bestEl.textContent = String(best);
  }

  function die(){
    alive = false;
    stop();
    showOverlay('Game Over', 'Score ' + score + ' — press Reset');
    draw();
  }

  function tick(){
    if (!alive) return;
    dir = nextDir;
    var d = DIRS[dir];
    var head = snake[0];
    var nx = head[0] + d[0];
    var ny = head[1] + d[1];

    // wall
    if (nx < 0 || ny < 0 || nx >= W || ny >= H){ die(); return; }

    var eating = !!food && nx === food[0] && ny === food[1];

    // self collision (the tail cell frees up unless we're growing)
    var limit = eating ? snake.length : snake.length - 1;
    for (var i = 0; i < limit; i++){
      if (snake[i][0] === nx && snake[i][1] === ny){ die(); return; }
    }

    snake.unshift([nx, ny]);
    if (eating){
      score += 1;
      updateHud();
      placeFood();
      if (speed > 60) speed = Math.max(60, speed - 2);
      if (running) restartTimer();
    } else {
      snake.pop();
    }
    draw();
  }

  function setDir(d){
    if (!DIRS[d]) return false;
    if (OPP[dir] === d) return false;   // 180° reversal ignored
    nextDir = d;
    return true;
  }

  function setFood(x, y){
    x = Math.floor(x); y = Math.floor(y);
    if (x < 0 || y < 0 || x >= W || y >= H) return false;
    food = [x, y];
    draw();
    return true;
  }

  /* ---------- rendering ---------- */

  function roundRect(x, y, w, h, r){
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function draw(){
    ctx.fillStyle = '#0d131b';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.035)';
    ctx.lineWidth = 1;
    for (var i = 1; i < W; i++){
      ctx.beginPath(); ctx.moveTo(i * CELL + .5, 0); ctx.lineTo(i * CELL + .5, canvas.height); ctx.stroke();
    }
    for (var j = 1; j < H; j++){
      ctx.beginPath(); ctx.moveTo(0, j * CELL + .5); ctx.lineTo(canvas.width, j * CELL + .5); ctx.stroke();
    }

    // food
    if (food){
      var fx = food[0] * CELL + CELL / 2;
      var fy = food[1] * CELL + CELL / 2;
      ctx.fillStyle = 'rgba(255,93,115,0.25)';
      ctx.beginPath(); ctx.arc(fx, fy, CELL * 0.46, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#ff5d73';
      ctx.beginPath(); ctx.arc(fx, fy, CELL * 0.30, 0, Math.PI * 2); ctx.fill();
    }

    // snake, tail -> head so the head paints on top
    if (snake){
      for (var k = snake.length - 1; k >= 0; k--){
        var seg = snake[k];
        var t = snake.length > 1 ? k / (snake.length - 1) : 0;
        var pad = 1.5 + t * 1.5;
        var x = seg[0] * CELL + pad, y = seg[1] * CELL + pad;
        var s = CELL - pad * 2;
        if (k === 0){
          ctx.fillStyle = alive ? '#7ef0ad' : '#6b7a8c';
        } else {
          var g = Math.round(220 - t * 90);
          ctx.fillStyle = alive ? 'rgb(61,' + g + ',132)' : 'rgb(80,92,106)';
        }
        roundRect(x, y, s, s, Math.max(2, s * 0.28));
        ctx.fill();
      }
      // eyes
      var hd = snake[0];
      var d = DIRS[dir] || [1, 0];
      var hx = hd[0] * CELL + CELL / 2, hy = hd[1] * CELL + CELL / 2;
      var ox = d[1] !== 0 ? CELL * 0.20 : 0, oy = d[0] !== 0 ? CELL * 0.20 : 0;
      var fwx = d[0] * CELL * 0.16, fwy = d[1] * CELL * 0.16;
      ctx.fillStyle = '#0b0f14';
      ctx.beginPath(); ctx.arc(hx + fwx + ox, hy + fwy + oy, CELL * 0.075, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(hx + fwx - ox, hy + fwy - oy, CELL * 0.075, 0, Math.PI * 2); ctx.fill();
    }
  }

  /* ---------- loop / controls ---------- */

  function restartTimer(){
    if (timer) clearInterval(timer);
    timer = setInterval(tick, speed);
  }
  function start(){
    if (!alive) return;
    running = true;
    hideOverlay();
    restartTimer();
  }
  function stop(){
    running = false;
    if (timer){ clearInterval(timer); timer = null; }
  }
  function pause(){
    if (running){
      stop();
      if (alive) showOverlay('Paused', 'Press Start to resume');
    } else if (alive){
      start();
    }
  }

  document.getElementById('start').addEventListener('click', start);
  document.getElementById('pause').addEventListener('click', pause);
  document.getElementById('reset').addEventListener('click', function(){
    stop();
    reset();
    showOverlay('Ready', 'Press Start');
  });

  var KEYS = {
    ArrowUp:'up', ArrowDown:'down', ArrowLeft:'left', ArrowRight:'right',
    w:'up', s:'down', a:'left', d:'right'
  };
  window.addEventListener('keydown', function(e){
    var k = KEYS[e.key];
    if (k){
      e.preventDefault();
      setDir(k);
      if (!running && alive) start();
      return;
    }
    if (e.key === ' '){ e.preventDefault(); pause(); }
  });

  reset();
  showOverlay('Ready', 'Press Start');

  window.game = {
    w: W,
    h: H,
    reset: reset,
    tick: tick,
    setDir: setDir,
    setFood: setFood,
    snake: function(){ return snake.map(function(s){ return [s[0], s[1]]; }); },
    food: function(){ return food ? [food[0], food[1]] : null; },
    alive: function(){ return alive; },
    score: function(){ return score; },
    start: start,
    pause: pause,
    draw: draw
  };
})();
</script>
</body>
</html>
